// delta_T (TT - UT1) in seconds at a TT instant; falls back to the
// Espenak-Meeus polynomial (astro.hpp) outside 1973..2027.
inline double delta_t_seconds_full(double jd_tt);

inline double delta_t_interp(double jd_tt) {
    if (jd_tt <= kTT[0] || jd_tt >= kTT[kN - 1]) return 1e300;
    int lo = 0, hi = kN - 1;
    while (hi - lo > 1) {
        const int mid = (lo + hi) / 2;
        if (kTT[mid] <= jd_tt) lo = mid; else hi = mid;
    }
    const double f = (jd_tt - kTT[lo]) / (kTT[hi] - kTT[lo]);
    return kDT[lo] + f * (kDT[hi] - kDT[lo]);
}
